17	/// ## What it does
18	/// Checks for `if` statements (without `elif` or `else` branches) where the
19	/// body contains only `pass` or `...`
20	///
21	/// ## Why is this bad?
22	/// An `if` statement with an empty body either does nothing (when the
23	/// condition is side-effect-free) or could be replaced with just the
24	/// condition expression (when it has side effects). This pattern commonly
25	/// arises when auto-fixers remove unused imports from conditional blocks
26	/// (e.g., version-dependent imports), leaving behind an empty skeleton.
27	///
28	/// ## Example
29	/// ```python
30	/// import sys
31	///
32	/// if sys.version_info >= (3, 11):
33	///     pass
34	/// ```
35	///
36	/// Use instead:
37	/// ```python
38	/// import sys
39	/// ```
40	///
41	/// ## Fix safety
42	/// When the condition is side-effect-free, the fix removes the entire `if`
43	/// statement.
44	///
45	/// When the condition has side effects (e.g., a function call), the fix
46	/// replaces the `if` statement with just the condition as an expression
47	/// statement, preserving the side effects.
48	///
49	/// Note: conditions consisting solely of a name expression (like
50	/// `if x: pass`) are treated as side-effect-free, even though `if x`
51	/// implicitly calls `x.__bool__()` (or `x.__len__()`), which could have
52	/// side effects if overridden. In practice this is very rare, but if you
53	/// rely on this behavior, suppress the diagnostic with `# noqa: RUF050`.
54	///
55	/// ## Related rules
56	/// - [`needless-else (RUF047)`]: Detects empty `else` clauses. For `if`/`else`
57	///   statements where all branches are empty, `RUF047` first removes the empty
58	///   `else`, and then this rule catches the remaining empty `if`.
59	/// - [`empty-type-checking-block (TC005)`]: Detects empty `if TYPE_CHECKING`
60	///   blocks specifically.
61	#[derive(ViolationMetadata)]
62	#[violation_metadata(preview_since = "0.15.8")]
63	pub(crate) struct UnnecessaryIf;
64	
65	impl AlwaysFixableViolation for UnnecessaryIf {
66	    #[derive_message_formats]
67	    fn message(&self) -> String {
68	        "Empty `if` statement".to_string()
69	    }
70	
71	    fn fix_title(&self) -> String {
72	        "Remove the `if` statement".to_string()
73	    }
74	}
