76	/// RUF050
77	pub(crate) fn unnecessary_if(checker: &Checker, stmt: &StmtIf) {
78	    let StmtIf {
79	        test,
80	        body,
81	        elif_else_clauses,
82	        ..
83	    } = stmt;
84	
85	    // Only handle bare `if` blocks — `elif`/`else` branches are handled by
86	    // RUF047 (needless-else)
87	    if !elif_else_clauses.is_empty() {
88	        return;
89	    }
90	
91	    if !is_stub_body(body) {
92	        return;
93	    }
94	
95	    // Skip `if TYPE_CHECKING` blocks — handled by TC005
96	    if typing::is_type_checking_block(stmt, checker.semantic()) {
97	        return;
98	    }
99	
100	    // Skip if the body contains a comment
101	    if if_contains_comments(stmt, checker) {
102	        return;
103	    }
104	
105	    let has_side_effects = contains_effect(test, |id| checker.semantic().has_builtin_binding(id))
106	        || any_over_expr(test, &|expr| matches!(expr, Expr::Named(_)));
107	
108	    let mut diagnostic = checker.report_diagnostic(UnnecessaryIf, stmt.range());
109	
110	    if has_side_effects {
111	        // Replace `if cond: pass` with `cond` as an expression statement.
112	        // Walrus operators need parentheses to be valid as statements.
113	        let condition_text = checker.locator().slice(test.range());
114	        let replacement = if test.is_named_expr() {
115	            format!("({condition_text})")
116	        } else {
117	            condition_text.to_string()
118	        };
119	        let edit = Edit::range_replacement(replacement, stmt.range());
120	        diagnostic.set_fix(Fix::safe_edit(edit));
121	    } else {
122	        let stmt_ref = checker.semantic().current_statement();
123	        let parent = checker.semantic().current_statement_parent();
124	        let edit = fix::edits::delete_stmt(stmt_ref, parent, checker.locator(), checker.indexer());
125	        let fix = Fix::safe_edit(edit).isolate(Checker::isolation(
126	            checker.semantic().current_statement_parent_id(),
127	        ));
128	        diagnostic.set_fix(fix);
129	    }
130	}
